vec3 ret1, neu, mus;
vec2 rs,rs2,uv1,uv2, uv3,uv4,uv6,dz,dz1;
shader_body
{
vec2 uv2;
//uv = (uv-0.5) * uAspect.xy;
dz = 0;
vec2 hor = vec2((1.0/uTexSize.x), 0.0 );
vec2 ver = vec2( 0.0 ,(1.0/uTexSize.y));
float dist = 1;
float inten = 1;
ret1 = 0;
int anz = 3;
int n = 0;
uv4 = (uv+.01);
dz.x = lum(GetPixel(uv4+hor)- GetPixel (uv4-hor));
dz.y = lum(GetPixel(uv4+ver)- GetPixel (uv4-ver));
mus = GetPixel(uv+.0*dz)+.0;
uv2 = uv-.5;
dz = 0;
while (n <= anz) {
dist = 1.0 - fract(1.0/anz*n+uTime / 2.0); //evtl sqrt !;
inten =  sqrt(dist)*(1.0 - dist) * 2.0;
uv3 = 2.0 * uv2*dist +.5;
//    uv3 *= uAspect.yx;
uv3 = fract(uv3);
neu = GetPixel(uv3)+GetBlur1(uv3).xy;
ret1 = max(ret1,neu*inten);
n++;
}
ret = ret1.bgr*(.5+mus) + 3.0*mus*(.1+ret1);
//ret = GetPixel(uv_orig) * 2.0;
}

